/**
 * Where a provider's page is on everyapp.com: one page per company
 * (`landing-page/content/docs/providers/<company>.mdx`), each with a
 * section per way in (API key, connect accounts, sign in). A catalog
 * entry or OAuth preset maps to its company's page; a provider a Gateway
 * registered from its own spec has none, so it gets the page on custom
 * providers.
 */
import { CAPABILITIES, OAUTH_PRESETS } from "@every-app/sdk/internal";
// The same map the pages are generated by (src/docs/providerPages.ts), so a link never misses its page.
import { COMPANY_OF } from "@/docs/providerGuides";

const SITE = "https://everyapp.com";

/** The company page `id` is on: `google` for `google-workspace`, `github` for `github-oauth`. */
function providerCompany(id: string): string {
  return COMPANY_OF[id] ?? id.replace(/-oauth$/, "");
}

/** The page to read before setting `id` up: its company's, or the custom-providers page for one the catalog doesn't ship. */
export function providerDocsUrl(id: string): string {
  const shipped = Object.hasOwn(CAPABILITIES, id) || Object.hasOwn(OAUTH_PRESETS, id);
  return `${SITE}/docs/providers/${shipped ? providerCompany(id) : "custom"}`;
}
